insert into public.dialogues (key, speaker_external_id, source_path, source_metadata) select key, speaker_external_id, source_path, source_metadata from jsonb_to_recordset($seed$[{"key":"the_royal_impostor_homework_q01_finish","speaker_external_id":"City Gaurd Info","source_path":"_registry\\dialogues\\the_royal_impostor_homework.yaml","source_metadata":{}},{"key":"the_royal_impostor_homework_q01_start","speaker_external_id":"City Gaurd Info","source_path":"_registry\\dialogues\\the_royal_impostor_homework.yaml","source_metadata":{}}]$seed$::jsonb) as entries(key text, speaker_external_id text, source_path text, source_metadata jsonb) on conflict (key) do update set speaker_external_id = excluded.speaker_external_id, source_path = excluded.source_path, source_metadata = excluded.source_metadata, updated_at = now();
insert into public.dialogue_lines (dialogue_id, locale, line_order, content, line_format) select dialogues.id, lines.locale, lines.line_order, lines.content, lines.line_format from jsonb_to_recordset($seed$[{"dialogue_key":"the_royal_impostor_homework_q01_finish","locale":"he","line_order":0,"content":"העגלה ריקה שוב, וכל אחד מצא את הדבר שלו בזכות הרשימה שלכם.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_homework_q01_finish","locale":"he","line_order":1,"content":"ויל לקח את ארוחת הצהריים שלו, השומרים את המפה שלהם, והציירת את הכריכים שלה.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_homework_q01_finish","locale":"he","line_order":2,"content":"זכרו: my = שלי, your = שלך או שלכם, his = שלו, her = שלה, our = שלנו, their = שלהם.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_homework_q01_finish","locale":"he","line_order":3,"content":"כל הכבוד. עשיתם את שיעורי הבית לבד.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_homework_q01_start","locale":"he","line_order":0,"content":"שלום שוב! אחרי החגיגה כל דבר חזר לבעלים שלו, ועגלת האבדות נשארה ריקה.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_homework_q01_start","locale":"he","line_order":1,"content":"אבל הבוקר השער היה עמוס, ועכשיו יש בעגלה דברים חדשים שאנשים שכחו.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_homework_q01_start","locale":"he","line_order":2,"content":"זוכרים את הרשימה הקרועה? היום אתם כותבים רשימה חדשה, כדי שכל אחד ימצא את הדבר שלו.","line_format":"plain_text"},{"dialogue_key":"the_royal_impostor_homework_q01_start","locale":"he","line_order":3,"content":"אין היום שום דבר חדש. אני חוזר לשמור על השער, ואתם עושים הכול לבד.","line_format":"plain_text"}]$seed$::jsonb) as lines(dialogue_key text, locale text, line_order integer, content text, line_format text) join public.dialogues on dialogues.key = lines.dialogue_key on conflict (dialogue_id, locale, line_order) do update set content = excluded.content, line_format = excluded.line_format;
